\begin{corollary}
\label{topping-maxpr-negative-scalar-lower-bound}
\source{topping:page-0047}
\dcref{ch3:2.5}
\group{maximum-principle}

For a Ricci flow on a closed manifold, defined for $t\in(0,T]$,
\[
R\geq-\frac{n}{2t}
\]
for every $t\in(0,T]$.
\end{corollary}

